"""Render the bilingual 132-output diagnostic report. Never runs model inference."""
from pathlib import Path
import html,json
from bs4 import BeautifulSoup
ROOT=Path(__file__).resolve().parents[1]
DEST=ROOT/'website/runs/2026-11-24-language-lab'
def t(cs,en,tag='span',cls=''):
    esc=lambda x:html.escape(x,quote=True)
    return f'<{tag} data-cs="{esc(cs)}" data-en="{esc(en)}"'+(f' class="{cls}"' if cls else '')+f'>{esc(en)}</{tag}>'
def a(url,cs,en):return f'<a href="{url}">{t(cs,en)}</a>'
def section(id,cs,en,body):return f'<section class="section" id="{id}">{t(cs,en,"h2")}{body}</section>'
body='<header class="page-intro"><span class="eyebrow">LANGUAGE LAB · 24 / 11 / 2026</span>'+t('Co se při překladu mezi jazyky ztratí?','What gets lost between languages?','h1')+t('Deset směrů, dvanáct krátkých herních situací a 132 skutečných výstupů. Prohlédni si, co malý lokální model zvládne — i kde mění význam.','Ten directions, twelve short gaming situations and 132 actual outputs. See what a small local model gets right — and where it changes the meaning.','p','lead')+'</header>'
body+='<nav class="jump-links">'+a('#takeaways','Co jsme zjistili','What we found')+a('#scores','Skóre a odezva','Scores & latency')+a('#examples','Prohlédnout překlady','Explore translations')+a('#method','Metoda a sestava','Method & setup')+a('#data','Data ke stažení','Download the data')+'</nav>'
body+='<div class="notice warning">'+t('Malý diagnostický soubor, nikoli žebříček kvality jazyků. Hodnocení provedl Codex přímým čtením všech výstupů v tomto chatu; nebylo zasláno hodnoticímu API. Není to slepý test ani ověření rodilými mluvčími.','A small diagnostic set, not a ranking of language quality. Codex assessed every output directly in this chat; no judge API was called. This is neither a blind study nor native-speaker validation.')+'</div>'
body+='<div class="cards"><article class="card"><div class="number">132</div>'+t('uložených překladů','saved translations','span','label')+t('120 × TranslateGemma 4B Q4_K_M, 12 × CUNI-MH 7B Q3_K_M pro kontrolu EN → CS.','120 × TranslateGemma 4B Q4_K_M, 12 × CUNI-MH 7B Q3_K_M as an EN → CS control.','p')+'</article><article class="card"><div class="number">0.36–0.53 s</div>'+t('rozsah mediánů samotného překladu','range of text-only translation medians','span','label')+t('RTX 4050 Laptop 6 GB / CUDA. OCR, FG a NR byly vypnuté. Doba načtení modelu je zvlášť.','RTX 4050 Laptop 6 GB / CUDA. OCR, FG and NR were off. Model startup is reported separately.','p')+'</article><article class="card"><div class="number">$0</div>'+t('nově utracených API kreditů','new API credit spent','span','label')+t('Modely běžely místně. Ani překlady, ani jejich hodnocení nepoužily placený API klíč.','Models ran locally. Neither translations nor their assessment used a paid API key.','p')+'</article></div>'
findings=[('Čeština potřebuje pozornost','Czech needs attention','Na stejných 12 EN → CS vstupech má CUNI 95,8/100, Gemma 77,1/100. Gemma často chybuje ve skloňování; někdy poškodí i význam. Je to výsledek tohoto malého souboru.','On the same 12 EN → CS inputs, CUNI scores 95.8/100 and Gemma 77.1/100. Gemma often mishandles Czech inflection and sometimes the meaning. This finding applies to this small set.'),('Plynulá japonština nemusí být správná','Fluent Japanese can still be wrong','CS → JA: šípy se změnily na stonky a modrý lektvar na modré pero. Proto hodnotíme význam a přirozenost odděleně. Oba chyby jsou níže v původním znění.','CS → JA turned arrows into stems and a blue potion into a blue pen. That is why meaning and fluency are scored separately. Both failures appear verbatim below.'),('Čísla a jednoduché pokyny často zůstaly','Numbers and simple instructions often survived','Model obvykle zachoval tři sekundy, počet šípů či čas 18:45. Horší byly vztahy mezi postavami, pokyny versus minulý děj a některé idiomy.','The model generally preserved three seconds, the arrow count and 18:45. Character relationships, instructions versus past events, and some idioms proved harder.')]
body+=section('takeaways','Nejdřív to podstatné','The main findings','<div class="cards">'+''.join('<article class="card">'+t(c,e,'h3')+t(dc,de,'p')+'</article>' for c,e,dc,de in findings)+'</div>')
headers=[('Model','Model'),('Směr','Direction'),('n','n'),('Skóre / 100','Score / 100'),('Význam / 4','Meaning / 4'),('Jazyk / 4','Fluency / 4'),('Medián','Median'),('P95','P95'),('Vážnější změny významu','Major meaning errors')]
body+=section('scores','Stejné situace, různé směry','Same situations, different directions',t('Skóre je průměr posouzení 12 výstupů. Počet vážnějších změn znamená význam ≤ 2/4. P95 je při 12 vzorcích maximum; nelze z něj odhadnout dlouhodobé špičky. Klepnutím na směr otevřeš jeho příklady.','Scores average 12 assessed outputs. Major meaning errors count meaning scores ≤ 2/4. With 12 samples, nearest-rank P95 is the maximum; it cannot establish long-run tail latency. Select a direction to inspect its examples.','p')+'<div class="table-wrap" tabindex="0"><table><thead><tr>'+''.join('<th scope="col">'+t(c,e)+'</th>' for c,e in headers)+'</tr></thead><tbody id="language-scores"></tbody></table></div>')
body+=section('examples','Přečti si skutečné výstupy','Read the actual outputs',t('Texty nejsou dodatečně opravené. Hodnocení vysvětluje chybu přímo u výstupu. Referenční věta je jedna možná formulace; přípustné nejednoznačnosti nepenalizujeme jen za odlišnost od ní.','Outputs have not been corrected. Each assessment explains the issue beside the output. The reference is one possible rendering; valid ambiguities are not penalized merely for differing from it.','p')+'<div class="tools"><label>'+t('Směr překladu','Translation direction')+'<select id="pair-filter"></select></label><label>'+t('Model','Model')+'<select id="model-filter"><option value="all">'+t('Oba modely','Both models')+'</option><option value="translategemma-4b-q4km">TranslateGemma 4B Q4_K_M</option><option value="cuni-q3km">CUNI-MH 7B Q3_K_M</option></select></label><label>'+t('Výběr příkladů','Example selection')+'<select id="score-filter"><option value="all">'+t('Všechny','All')+'</option><option value="errors">'+t('Význam ≤ 2/4','Meaning ≤ 2/4')+'</option><option value="perfect">'+t('Skóre 100/100','Score 100/100')+'</option></select></label><label>'+t('Řazení','Order')+'<select id="sort-filter"><option value="input">'+t('Pořadí vstupů','Input order')+'</option><option value="worst">'+t('Nejnižší skóre','Lowest score')+'</option><option value="slowest">'+t('Nejdelší čas','Slowest')+'</option></select></label></div><p id="case-count" role="status"></p><div id="language-cases"></div><div class="pagination"><button id="previous" type="button">'+t('← Předchozí','← Previous')+'</button><span id="page-count"></span><button id="next" type="button">'+t('Další →','Next →')+'</button></div>')
methods=[('Co přesně běželo','What actually ran','Windows 11 (build 26200), NVIDIA GeForce RTX 4050 Laptop 6 GB, ovladač 610.62, CUDA. Model byl celý na GPU, jeden po druhém. Žádné OCR, enhancer, FG ani překladová cache.','Windows 11 (build 26200), NVIDIA GeForce RTX 4050 Laptop 6 GB, driver 610.62, CUDA. One model at a time, fully on GPU. No OCR, enhancement, FG or translation cache.'),('Vstupy a rozsah','Inputs and scope','12 vět vytvořených pro tento test, každá v šesti jazycích. Nejde o dialogy vytažené z her. Gemma: deset směrů, jeden průchod. CUNI: jen EN → CS. Referenční texty připravil Codex a nemají nezávislou jazykovou revizi.','12 authored sentences, each in six languages. These are not extracted game scripts. Gemma: ten directions, one pass. CUNI: EN → CS only. References were prepared by Codex and have no independent linguistic review.'),('Čas a zahřátí','Timing and warm-up','Měříme wall-clock čas volání GpuTranslator.translate včetně místního HTTP požadavku a zpracování odpovědi. Konstruktor model zahřeje jednou; před každým směrem běží ještě první věta mimo skórované měření. První měřená věta tedy může těžit ze stejného promptu.','Wall-clock time around GpuTranslator.translate includes the local HTTP request and response handling. The constructor warms the model once; each direction then warms up on its first sentence outside the scored run. The first measured sentence can therefore benefit from the repeated prompt.'),('Načtení a paměť','Startup and memory','Gemma: 11,69 s od spuštění konstruktoru, runtime hlásí 2,56 GiB na GPU. CUNI: 12,47 s a 3,59 GiB. Start zahrnuje kontrolu, import a úvodní inferenci. VRAM je údaj runtime pro model, nikoli celá spotřeba počítače.','Gemma: 11.69 s from constructor start; runtime reports 2.56 GiB on GPU. CUNI: 12.47 s and 3.59 GiB. Startup includes verification, import and initial inference. VRAM is the runtime’s model allocation, not total computer usage.'),('Jak vzniklo skóre','How scores were assigned','Jeden neslepý průchod všech 132 výstupů, přímé posouzení Codexem. Význam 0–4: 4 zachován, 3 drobný posun, 2 důležitá změna, 1 ztracený hlavní smysl, 0 chybí. Jazyk 0–4: 4 přirozený, 3 drobná neobratnost, 2 gramatické chyby, 1 silně zkomolený, 0 nečitelný. Skóre = 12,5 × (význam + jazyk).','One unblinded pass over all 132 outputs, assessed directly by Codex. Meaning 0–4: 4 preserved, 3 minor shift, 2 important distortion, 1 main meaning lost, 0 absent. Fluency 0–4: 4 natural, 3 slight awkwardness, 2 grammar errors, 1 severely malformed, 0 unreadable. Score = 12.5 × (meaning + fluency).'),('Co z toho nevyvozovat','What this cannot establish','132 výstupů není 132 nezávislých situací: významů je jen 12 a reference jsou paralelní. Není zde měřena kvalita OCR ani zpoždění při hraní. Zvlášť u japonštiny je skóre orientační a zaslouží revizi rodilým mluvčím.','132 outputs are not 132 independent situations: there are only 12 meanings and the references are parallel. OCR quality and in-game delay are not measured here. Japanese scores in particular are exploratory and warrant native-speaker review.')]
body+=section('method','Jak jsme testovali','How we tested','<div class="method-grid">'+''.join('<article>'+t(c,e,'h3')+t(dc,de,'p')+'</article>' for c,e,dc,de in methods)+'</div>'+t('Použitý kód: cd2b0954aaed17e5ffa40b1e9120178367b3cc63. Kontext 2048, teplota 0, seed 20261119; efektivní parametry a přesné SHA-256 modelů jsou v metadatech. Žádné přepromptování podle výsledku ani výběr nejlepšího z více pokusů.','Code used: cd2b0954aaed17e5ffa40b1e9120178367b3cc63. Context 2048, temperature 0, seed 20261119; effective options and exact model SHA-256 hashes are in the metadata. No outcome-driven reprompting or best-of-many selection.','p','fine'))
body+=section('data','Zkontroluj si to sám','Check the evidence yourself','<div class="download-links">'+a('data/translations.csv','Všech 132 výstupů a hodnocení · CSV','All 132 outputs and assessments · CSV')+a('data/report.json','Strukturovaný report · JSON','Structured report · JSON')+a('data/outputs.jsonl','Neupravené výstupy a časy · JSONL','Unedited outputs and timings · JSONL')+a('data/dataset.json','Vstupy a reference · CC0','Inputs and references · CC0')+a('data/metadata.json','Sestava, modely a parametry','Hardware, models and settings')+a('data/sha256.json','Kontrolní součty souborů','File checksums')+a('https://github.com/tomik520i/FrameLab/blob/main/tools/benchmark_language_lab.py','Opakování testu · Python / GitHub','Rerun the test · Python / GitHub')+'</div><div class="actions">'+a('../../results/','← Všechny výsledky a metody','← All results & methods')+a('../../guide/multilingual-en.html','Nastavit vícejazyčné titulky →','Set up multilingual subtitles →')+'</div>')
body+='<footer class="footer"><span>FRAME/LAB · preview.18</span>'+a('../../licenses/','Licence','Licenses')+'</footer>'
markup='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'+t('FrameLab — 132 vícejazyčných překladů','FrameLab — 132 multilingual translations','title')+'<link rel="icon" href="../../assets/icon.svg"><link rel="stylesheet" href="../../assets/fonts/fonts.css"><link rel="stylesheet" href="../../explore.css?v=20261124"></head><body><main id="main">'+body+'<noscript><p>This interactive viewer needs JavaScript. Full data: <a href="data/translations.csv">CSV</a>. / Pro interaktivní výpis zapni JavaScript; všechna data jsou v CSV.</p></noscript></main><script src="language-lab.js?v=20261124" defer></script></body></html>'
soup=BeautifulSoup(markup.replace('Oba chyby','Obě chyby'),'html.parser')
for option in soup.select('option'):
    span=option.find('span',attrs={'data-cs':True})
    if span:
        option['data-cs']=span['data-cs'];option['data-en']=span['data-en'];option.string=span.get_text()
(DEST/'index.html').write_text(str(soup),encoding='utf-8')
print('Language lab HTML rendered; run localize_website.py afterwards.')
